import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // root container
  const root = new Group();

  // plane geometry (size will be controlled by parent scaling)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'), // surface color as fallback
    transparent: true,
  });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // load texture if provided
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {};
  const inkColor = colors.ink ?? '#16161d';

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: inkColor,
      align: 'left',
    });
    // lift text slightly above the plane to avoid z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // no interactive handlers for this node
  root.userData.handlers = {};

  // cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // clear any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return root;
}
